<script lang="ts">import {goto} from '$app/navigation';import {onMount} from 'svelte';import PhotoImage from '$lib/components/PhotoImage.svelte';import PhotoFigure from '$lib/components/PhotoFigure.svelte';import ScrollCue from '$lib/components/ScrollCue.svelte';import {dateLabel,monthYear} from '$lib/format';let {data}=$props();let ready=$state(false);let privateClicks=0;let reset:ReturnType<typeof setTimeout>;onMount(()=>ready=true);function privateEntry(){privateClicks+=1;clearTimeout(reset);reset=setTimeout(()=>privateClicks=0,2500);if(privateClicks===6)goto('/admin');}</script>
<svelte:head><title>Westin Perry — A personal archive</title></svelte:head>
<section class="hero opening-screen" data-hydrated={ready}><div class="hero-copy"><div class="hero-name-wrap"><h1 class="hero-name">Westin<br/>Perry</h1><button class="secret-entry" type="button" tabindex="-1" aria-hidden="true" onclick={privateEntry}></button></div><span class="accent-rule"></span><h2>{data.settings.hero_headline}</h2><p>{data.settings.hero_copy}</p></div><div class="hero-image">{#if data.settings.hero_key}<PhotoImage photo={{storage_key:data.settings.hero_key,alt_text:data.settings.hero_alt}} eager/>{:else}<div class="image-fallback">Rural landscape — add a hero photo in Private</div>{/if}</div><ScrollCue target="home-content"/></section>
