<section class="home-section"><div class="section-head"><h2>Recent Photos</h2><a class="text-link" href="/photos">View all photos →</a></div><div class="photo-grid">{#each data.photos as photo}<PhotoFigure {photo}/>{/each}</div></section>
<section class="home-section"><div class="section-head"><h2>Log</h2><a class="text-link" href="/log">View full log →</a></div><div class="ledger">{#each data.logs as entry}<article><time datetime={new Date(entry.event_date).toISOString()}>{dateLabel(entry.event_date,{month:'short',day:'numeric'})}</time><div><h3>{entry.title}</h3>{#if entry.description}<p>{entry.description}</p>{/if}</div></article>{/each}</div></section>
